css:
*{margin:0;padding:0;box-sizing:border-box}
:root{
 --navy:#00091a;--navy2:#04122b;--navy3:#0b1c37;--navy4:#112645;
 --yellow:#FFC80A;--yellow2:#ffd747;
 --ink:#ffffff;--mut:#9fb0c6;--mut2:#7488a3;
 --line:rgba(255,255,255,.10);--line2:rgba(255,255,255,.16);
 --green:#2fd07a;--coral:#ff6f6f;
 --gut:40px;--rad:18px;
 --shadow:0 24px 60px -18px rgba(0,0,0,.55);
 --fdisp:'Plus Jakarta Sans',system-ui,sans-serif;
 --fbody:'Inter',system-ui,sans-serif;
}
html{scroll-behavior:smooth}
body{background:var(--navy);color:var(--ink);font-family:var(--fbody);line-height:1.6;
 -webkit-font-smoothing:antialiased;overflow-x:clip}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--fdisp);font-weight:800;line-height:1.08;letter-spacing:-.02em}
.wrap{max-width:1240px;margin:0 auto;padding:0 var(--gut)}
.acc{color:var(--yellow)}
.mut{color:var(--mut)}
.center{text-align:center}
section{position:relative}

/* reveal (pure CSS, Nifty-safe) */
.rv{animation:rvIn .8s cubic-bezier(.2,.7,.2,1) both}
.rv2{animation:rvIn .8s .12s cubic-bezier(.2,.7,.2,1) both}
.rv3{animation:rvIn .8s .24s cubic-bezier(.2,.7,.2,1) both}
@keyframes rvIn{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.rv,.rv2,.rv3{animation:none}}

/* buttons */
.btn{display:inline-flex;align-items:center;gap:9px;font-family:var(--fdisp);font-weight:800;
 font-size:16px;padding:15px 26px;border-radius:14px;cursor:pointer;border:0;transition:.18s;white-space:nowrap}
.btn svg{width:18px;height:18px}
.btn-y{background:var(--yellow);color:#08121f;box-shadow:0 12px 30px -8px rgba(255,200,10,.5)}
.btn-y:hover{background:var(--yellow2);transform:translateY(-2px)}
.btn-g{background:transparent;color:var(--ink);border:1.5px solid var(--line2)}
.btn-g:hover{border-color:var(--yellow);color:var(--yellow)}
.btn-sm{padding:12px 20px;font-size:15px}

/* eyebrow / pills */
.kick{display:inline-flex;align-items:center;gap:9px;font-family:var(--fdisp);font-weight:700;
 font-size:13px;letter-spacing:.16em;text-transform:uppercase;color:var(--yellow)}
.kick b{color:var(--ink);font-weight:700}
.pill{display:inline-flex;align-items:center;gap:9px;padding:8px 16px;border-radius:100px;
 background:rgba(255,200,10,.08);border:1px solid rgba(255,200,10,.28);color:#f4d98a;
 font-size:13.5px;font-weight:600}
.pill .dot{width:8px;height:8px;border-radius:50%;background:var(--yellow);box-shadow:0 0 0 4px rgba(255,200,10,.18)}
.eyebrow{font-family:var(--fdisp);font-weight:800;font-size:13px;letter-spacing:.18em;
 text-transform:uppercase;color:var(--yellow);margin-bottom:16px;display:block}

/* ============ HEADER ============ */
.hdr{position:sticky;top:0;z-index:60;background:rgba(0,9,26,.82);
 backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}
.hdr-in{display:flex;align-items:center;gap:22px;height:94px}
.brand{display:flex;align-items:center;flex-shrink:0}
.brand img{height:62px;width:auto}
.nav{display:flex;align-items:center;gap:1px;margin-left:auto}
.nav a{position:relative;font-size:14.5px;font-weight:600;color:#cdd7e6;padding:9px 11px;border-radius:9px;transition:color .15s}
.nav a:hover{color:#fff}
.nav a.on{color:var(--yellow)}
/* TRON hover — glowing line sweeps under the link */
.nav a::after{content:"";position:absolute;left:11px;right:11px;bottom:4px;height:2px;border-radius:2px;
 background:linear-gradient(90deg,transparent,var(--yellow),transparent);
 transform:scaleX(0);transform-origin:left;opacity:0;transition:transform .3s ease,opacity .3s ease}
.nav a:hover::after{transform:scaleX(1);opacity:1;box-shadow:0 0 10px rgba(255,200,10,.7)}
.nav a.on::after{transform:scaleX(1);opacity:.9}
.nav .m-cta{display:none}
.nav-head{display:none}
.hdr-cta{display:flex;align-items:center;gap:10px;flex-shrink:0}
.nav-cb,.nav-lbl,.nav-ov{display:none}

@media(max-width:1240px){
 :root{--gut:26px}
 .hdr-in{gap:16px}
 .nav-lbl{display:inline-flex;align-items:center;justify-content:center;margin-left:auto;
  width:48px;height:48px;border-radius:13px;border:1px solid var(--line2);cursor:pointer;
  background:rgba(255,255,255,.03);transition:.2s}
 .nav-lbl:hover{border-color:var(--yellow);box-shadow:0 0 14px rgba(255,200,10,.25)}
 .nav-lbl span{position:relative;width:22px;height:2px;background:var(--yellow);border-radius:2px}
 .nav-lbl span::before,.nav-lbl span::after{content:"";position:absolute;left:0;width:22px;height:2px;background:var(--yellow);border-radius:2px}
 .nav-lbl span::before{top:-7px}.nav-lbl span::after{top:7px}
 .hdr-cta{display:none}
 /* backdrop */
 .nav-ov{display:block;position:fixed;inset:0;background:rgba(1,7,18,.6);backdrop-filter:blur(3px);
  z-index:65;opacity:0;pointer-events:none;transition:opacity .35s ease}
 /* slide-out panel */
 .nav{position:fixed;top:0;right:0;height:100dvh;width:min(360px,88vw);flex-direction:column;
  align-items:stretch;gap:2px;margin:0;padding:0 0 26px;background:#03102a;
  border-left:1px solid rgba(255,200,10,.18);box-shadow:-20px 0 60px rgba(0,0,0,.5);
  clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .4s cubic-bezier(.4,0,.2,1);
  z-index:70;overflow-y:auto;
  background-image:linear-gradient(rgba(255,200,10,.05) 1px,transparent 1px),
   linear-gradient(90deg,rgba(255,200,10,.05) 1px,transparent 1px),linear-gradient(180deg,#03102a,#040c1f);
  background-size:38px 38px,38px 38px,100% 100%}
 .nav>*{opacity:0;transform:translateX(16px);transition:opacity .3s ease,transform .3s ease}
 .nav-head{display:flex;align-items:center;justify-content:space-between;padding:20px 22px;
  border-bottom:1px solid rgba(255,255,255,.08);margin-bottom:12px}
 .nav-head img{height:50px;width:auto}
 .nav-close{position:relative;width:40px;height:40px;border-radius:11px;border:1px solid var(--line2);
  cursor:pointer;flex-shrink:0;transition:.2s}
 .nav-close:hover{border-color:var(--yellow);box-shadow:0 0 12px rgba(255,200,10,.3)}
 .nav-close::before,.nav-close::after{content:"";position:absolute;top:19px;left:10px;width:20px;height:2px;background:#fff;border-radius:2px}
 .nav-close::before{transform:rotate(45deg)}.nav-close::after{transform:rotate(-45deg)}
 .nav a{font-size:17px;font-weight:600;padding:15px 22px;margin:0 12px;border-radius:11px;
  border-bottom:0;overflow:hidden}
 .nav a::after{left:22px;right:auto;top:0;bottom:0;width:3px;height:auto;border-radius:2px;
  background:var(--yellow);transform:scaleY(0);transform-origin:top}
 .nav a:hover,.nav a.on{background:rgba(255,200,10,.08)}
 .nav a:hover::after,.nav a.on::after{transform:scaleY(1);opacity:1;box-shadow:0 0 12px rgba(255,200,10,.7)}
 .nav .m-cta{display:block;margin:18px 22px 6px;text-align:center;background:var(--yellow);
  color:#08121f;border-radius:13px;border:0;padding:15px}
 .nav .m-cta::after{display:none}
 .nav-cb:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto}
 .nav-cb:checked ~ .nav>*{opacity:1;transform:translateX(0);transition-delay:.12s}
 .nav-cb:checked ~ .nav-ov{opacity:1;pointer-events:auto}
}
@media(max-width:430px){:root{--gut:18px}.brand img{height:48px}}

/* ============ HERO ============ */
.hero{padding:78px 0 90px;background:
 radial-gradient(900px 520px at 78% -8%,rgba(255,200,10,.14),transparent 60%),
 radial-gradient(760px 500px at 8% 108%,rgba(35,110,220,.16),transparent 62%)}
.hero-grid{display:grid;grid-template-columns:1.08fr .92fr;gap:56px;align-items:center}
.hero h1{font-size:clamp(38px,5.4vw,66px);margin:20px 0 20px}
.hero h1 .u{position:relative;color:var(--yellow);white-space:nowrap}
.hero h1 .u::after{content:"";position:absolute;left:0;right:0;bottom:.02em;height:.14em;
 background:rgba(255,200,10,.32);border-radius:3px;z-index:-1}
.hero-lead{font-size:19px;color:var(--mut);max-width:560px;margin-bottom:28px}
.wait{display:flex;gap:10px;max-width:520px;margin-bottom:16px}
.wait input{flex:1;min-width:0;width:100%;padding:15px 18px;border-radius:13px;border:1px solid var(--line2);
 background:rgba(255,255,255,.05);color:#fff;font-size:15.5px;font-family:var(--fbody)}
.wait input::placeholder{color:#8598b2}
.wait input:focus{outline:none;border-color:var(--yellow);background:rgba(255,255,255,.08)}
.wait .btn{flex-shrink:0}
.microcopy{font-size:13.5px;color:var(--mut2);margin-bottom:24px}
.ticks{display:flex;flex-wrap:wrap;gap:9px 22px}
.tick{display:inline-flex;align-items:center;gap:8px;font-size:14.5px;font-weight:600;color:#c7d3e3}
.tick svg{width:18px;height:18px;color:var(--green);flex-shrink:0}

/* hero visual */
.hero-vis{position:relative}
.hv-card{background:linear-gradient(180deg,#0c1e3c,#081733);border:1px solid var(--line2);
 border-radius:22px;padding:20px;box-shadow:var(--shadow)}
.hv-top{display:flex;align-items:center;gap:8px;padding-bottom:14px;border-bottom:1px solid var(--line);margin-bottom:16px}
.hv-dot{width:11px;height:11px;border-radius:50%;background:#37507a}
.hv-url{margin-left:10px;font-size:12.5px;color:#8ba0bf;background:rgba(255,255,255,.05);
 padding:5px 12px;border-radius:8px;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hv-prompt{display:flex;gap:10px;align-items:flex-start;background:rgba(255,200,10,.08);
 border:1px solid rgba(255,200,10,.25);border-radius:13px;padding:13px 14px;margin-bottom:16px}
.hv-prompt .rb{width:30px;height:30px;border-radius:9px;flex-shrink:0;background:#0a1428;
 display:grid;place-items:center;font-size:16px}
.hv-prompt p{font-size:13.5px;color:#e7edf6}
.hv-prompt .cursor{display:inline-block;width:2px;height:1em;background:var(--yellow);
 vertical-align:-2px;animation:bk 1s steps(1) infinite}
@keyframes bk{50%{opacity:0}}
.hv-rows{display:grid;gap:9px}
.hv-row{height:12px;border-radius:6px;background:linear-gradient(90deg,rgba(255,255,255,.14),rgba(255,255,255,.04));
 animation:sh 1.6s ease-in-out infinite}
.hv-row:nth-child(2){width:82%;animation-delay:.1s}
.hv-row:nth-child(3){width:64%;animation-delay:.2s}
.hv-row.blk{height:52px;background:linear-gradient(90deg,rgba(255,200,10,.16),rgba(255,200,10,.05));width:100%}
@keyframes sh{50%{opacity:.55}}
.hv-badge{position:absolute;top:-26px;right:-14px;width:96px;height:96px;filter:drop-shadow(0 14px 28px rgba(0,0,0,.5))}
.hv-chip{position:absolute;bottom:-20px;left:-16px;background:#0a1a33;border:1px solid var(--line2);
 border-radius:13px;padding:11px 15px;display:flex;align-items:center;gap:10px;box-shadow:var(--shadow)}
.hv-chip .ic{width:34px;height:34px;border-radius:9px;background:rgba(47,208,122,.15);
 display:grid;place-items:center;color:var(--green)}
.hv-chip .ic svg{width:18px;height:18px}
.hv-chip b{font-size:13.5px;display:block}
.hv-chip small{font-size:11.5px;color:var(--mut)}

/* ============ MARQUEE / PROOF ============ */
.proof{padding:30px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--navy2)}
.proof-in{display:flex;align-items:center;gap:34px;flex-wrap:wrap;justify-content:center}
.proof .lbl{font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:var(--mut2);font-weight:700}
.proof .tech{display:flex;align-items:center;gap:26px;flex-wrap:wrap;justify-content:center}
.proof .tech span{font-family:var(--fdisp);font-weight:800;font-size:17px;color:#c3cfe0;opacity:.9}
.proof .tech span .acc{color:var(--yellow)}

/* section head */
.sec{padding:88px 0}
.sec-head{max-width:720px;margin:0 auto 52px;text-align:center}
.sec-head h2{font-size:clamp(30px,4vw,46px);margin-bottom:16px}
.sec-head p{font-size:18px;color:var(--mut)}

/* problem cards */
.prob{background:var(--navy2)}
.pgrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}
.pcard{background:var(--navy3);border:1px solid var(--line);border-radius:var(--rad);padding:26px 22px;min-width:0}
.pcard .ic{width:48px;height:48px;border-radius:13px;background:rgba(255,111,111,.13);
 display:grid;place-items:center;color:var(--coral);margin-bottom:16px}
.pcard .ic svg{width:24px;height:24px}
.pcard h3{font-size:18px;margin-bottom:8px}
.pcard p{font-size:14.5px;color:var(--mut)}
.prob-foot{text-align:center;margin-top:38px;font-size:18px;color:#dbe4f0}
.prob-foot b{color:var(--yellow)}

/* how it works */
.steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;counter-reset:s}
.step{position:relative;background:var(--navy2);border:1px solid var(--line);border-radius:var(--rad);
 padding:34px 26px 30px;min-width:0}
.step::before{counter-increment:s;content:"0" counter(s);font-family:var(--fdisp);font-weight:800;
 font-size:52px;color:rgba(255,200,10,.22);line-height:1;display:block;margin-bottom:14px}
.step .ic{width:52px;height:52px;border-radius:14px;background:rgba(255,200,10,.12);
 display:grid;place-items:center;color:var(--yellow);margin-bottom:18px}
.step .ic svg{width:26px;height:26px}
.step h3{font-size:21px;margin-bottom:10px}
.step p{font-size:15px;color:var(--mut)}
.step .arw{position:absolute;top:50%;right:-31px;color:rgba(255,200,10,.4);z-index:2}
.step:last-child .arw{display:none}

/* feature groups */
.fgroup{margin-bottom:46px}
.fgroup:last-child{margin-bottom:0}
.fg-head{display:flex;align-items:center;gap:14px;margin-bottom:22px}
.fg-head .tag{font-family:var(--fdisp);font-weight:800;font-size:13px;letter-spacing:.1em;
 text-transform:uppercase;color:#08121f;background:var(--yellow);padding:6px 14px;border-radius:8px}
.fg-head .ln{flex:1;height:1px;background:var(--line)}
.fgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.fcard{background:var(--navy2);border:1px solid var(--line);border-radius:var(--rad);padding:24px 22px;
 min-width:0;transition:.18s}
.fcard:hover{border-color:rgba(255,200,10,.3);transform:translateY(-3px)}
.fcard .ic{width:44px;height:44px;border-radius:12px;background:rgba(255,200,10,.1);
 display:grid;place-items:center;color:var(--yellow);margin-bottom:15px}
.fcard .ic svg{width:22px;height:22px}
.fcard h3{font-size:16.5px;margin-bottom:7px}
.fcard p{font-size:14px;color:var(--mut)}

/* AI angle split */
.ai{background:var(--navy2)}
.ai-grid{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center}
.ai-demo{background:linear-gradient(180deg,#0c1e3c,#081633);border:1px solid var(--line2);
 border-radius:20px;padding:24px;box-shadow:var(--shadow)}
.ai-demo .say{background:rgba(255,255,255,.05);border:1px solid var(--line);border-radius:13px;
 padding:14px 16px;font-size:14.5px;color:#e7edf6;margin-bottom:12px;display:flex;gap:11px}
.ai-demo .say .rb{width:28px;height:28px;border-radius:8px;flex-shrink:0;background:#0a1428;display:grid;place-items:center}
.ai-arrow{text-align:center;color:var(--yellow);margin:6px 0 14px}
.ai-arrow svg{width:30px;height:30px;display:inline-block;transform:rotate(90deg)}
.ai-out{border:1px solid var(--line2);border-radius:13px;overflow:hidden}
.ai-out .bar{height:34px;background:#0a1932;display:flex;align-items:center;padding:0 14px;gap:6px;border-bottom:1px solid var(--line)}
.ai-out .bar i{width:9px;height:9px;border-radius:50%;background:#33496f;display:block}
.ai-out .body{padding:16px}
.ai-out .hh{height:22px;width:56%;border-radius:6px;background:rgba(255,200,10,.35);margin-bottom:12px}
.ai-out .ll{height:10px;border-radius:5px;background:rgba(255,255,255,.12);margin-bottom:8px}
.ai-out .ll.s{width:80%}.ai-out .ll.t{width:64%}
.ai-out .cta-fake{height:34px;width:130px;border-radius:9px;background:var(--yellow);margin-top:14px}
.ai ul.chk{list-style:none;margin:22px 0 28px}
.ai ul.chk li{display:flex;gap:12px;align-items:flex-start;margin-bottom:14px;font-size:16px;color:#d7e0ec}
.ai ul.chk li svg{width:22px;height:22px;color:var(--green);flex-shrink:0;margin-top:2px}

/* technology */
.tech-grid{display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:start}
.tsimple{display:grid;gap:16px}
.tstep{display:flex;gap:16px;background:var(--navy2);border:1px solid var(--line);border-radius:14px;padding:20px 22px;min-width:0}
.tstep .n{width:38px;height:38px;border-radius:11px;background:var(--yellow);color:#08121f;
 font-family:var(--fdisp);font-weight:800;display:grid;place-items:center;flex-shrink:0}
.tstep h4{font-size:16.5px;margin-bottom:4px}
.tstep p{font-size:14px;color:var(--mut)}
.tcard{background:var(--navy3);border:1px solid var(--line);border-radius:18px;padding:28px}
.tcard h3{font-size:19px;margin-bottom:6px}
.tcard>.mut{font-size:14px;margin-bottom:18px}
.tspec{list-style:none;display:grid;gap:2px}
.tspec li{display:flex;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);font-size:14.5px}
.tspec li:last-child{border-bottom:0}
.tspec li svg{width:18px;height:18px;color:var(--yellow);flex-shrink:0;margin-top:3px}
.tspec li b{color:#fff}.tspec li span{color:var(--mut)}
.tquote{margin-top:26px;background:linear-gradient(120deg,rgba(255,200,10,.1),rgba(255,200,10,.02));
 border:1px solid rgba(255,200,10,.25);border-radius:16px;padding:24px 26px;font-size:17px;
 font-family:var(--fdisp);font-weight:600;color:#f3e6b8;text-align:center}

/* comparison */
.cmp{background:var(--navy2)}
.cmp-scroll{overflow-x:auto;-webkit-overflow-scrolling:touch;border-radius:18px;border:1px solid var(--line);box-shadow:var(--shadow)}
table.cmp-t{width:100%;border-collapse:collapse;min-width:620px;background:var(--navy3)}
table.cmp-t th,table.cmp-t td{padding:18px 22px;text-align:left;border-bottom:1px solid var(--line);font-size:15px;vertical-align:top}
table.cmp-t thead th{font-family:var(--fdisp);font-size:16px;background:#0a1932}
table.cmp-t thead th:nth-child(3){background:rgba(255,200,10,.12);color:var(--yellow)}
table.cmp-t tbody td:nth-child(3){background:rgba(255,200,10,.05)}
table.cmp-t td:first-child{font-weight:700;color:#fff;width:150px}
table.cmp-t .old{color:#c3b0b0}
table.cmp-t .new{color:#eaf3ea;font-weight:600}
.cmp-cell{display:flex;gap:10px;align-items:flex-start}
.cmp-cell svg{width:18px;height:18px;flex-shrink:0;margin-top:2px}
.cmp-cell.n svg{color:var(--green)}.cmp-cell.o svg{color:var(--coral)}
.cmp-honest{text-align:center;margin-top:26px;font-size:15.5px;color:var(--mut);max-width:760px;margin-left:auto;margin-right:auto}

/* agencies */
.agy .box{background:linear-gradient(120deg,#0a1c3a,#06142c);border:1px solid var(--line2);
 border-radius:24px;padding:52px 48px;display:grid;grid-template-columns:1.2fr .8fr;gap:44px;
 align-items:center;box-shadow:var(--shadow);position:relative;overflow:hidden}
.agy .box::before{content:"";position:absolute;inset:0;background:radial-gradient(500px 300px at 100% 0,rgba(255,200,10,.14),transparent 60%)}
.agy .box>*{position:relative}
.agy h2{font-size:clamp(26px,3.4vw,40px);margin-bottom:16px}
.agy p{font-size:16.5px;color:var(--mut);margin-bottom:24px}
.agy .wl{list-style:none;display:grid;gap:12px}
.agy .wl li{display:flex;gap:11px;align-items:center;font-size:15.5px;color:#dbe4f0;font-weight:600}
.agy .wl li svg{width:20px;height:20px;color:var(--yellow);flex-shrink:0}

/* pricing / early bird */
.price .eb{max-width:680px;margin:0 auto 44px;text-align:center;background:rgba(255,200,10,.07);
 border:1px solid rgba(255,200,10,.28);border-radius:18px;padding:26px 30px}
.price .eb h3{font-size:22px;margin-bottom:8px}
.price .eb p{color:var(--mut);font-size:15.5px}
.tiers{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;align-items:stretch}
.tier{background:var(--navy2);border:1px solid var(--line);border-radius:20px;padding:32px 28px;min-width:0;
 display:flex;flex-direction:column}
