/* ============ AI GRID BACKGROUND (pure CSS animation, Nifty-safe) ============ */
.aigrid{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:0}
.aigrid::before{content:"";position:absolute;inset:-40px;
 background-image:linear-gradient(rgba(255,200,10,.06) 1px,transparent 1px),
  linear-gradient(90deg,rgba(255,200,10,.06) 1px,transparent 1px);
 background-size:48px 48px;
 -webkit-mask-image:radial-gradient(ellipse 80% 80% at 65% 25%,#000 0%,transparent 72%);
 mask-image:radial-gradient(ellipse 80% 80% at 65% 25%,#000 0%,transparent 72%);
 animation:gridpan 26s linear infinite}
@keyframes gridpan{to{background-position:48px 48px}}
.beam{position:absolute;opacity:.5;filter:blur(.2px)}
.beam.h{height:1.5px;width:200px;background:linear-gradient(90deg,transparent,rgba(255,200,10,.7),transparent)}
.beam.v{width:1.5px;height:170px;background:linear-gradient(180deg,transparent,rgba(255,200,10,.65),transparent)}
.beam.h1{top:20%;left:-200px;animation:beamx 8s linear infinite}
.beam.h2{top:64%;left:-200px;animation:beamx 11s linear infinite 2.5s}
.beam.v1{left:26%;top:-170px;animation:beamy 10s linear infinite 1s}
.beam.v2{left:72%;top:-170px;animation:beamy 13s linear infinite 3.5s}
@keyframes beamx{to{left:118%}}
@keyframes beamy{to{top:118%}}
.node{position:absolute;width:5px;height:5px;border-radius:50%;background:var(--yellow);
 box-shadow:0 0 9px 2px rgba(255,200,10,.55);opacity:.4;animation:nodepulse 3.4s ease-in-out infinite}
.node.n1{top:22%;left:26%}.node.n2{top:38%;left:72%;animation-delay:.8s}
.node.n3{top:64%;left:44%;animation-delay:1.6s}.node.n4{top:14%;left:58%;animation-delay:2.2s}
.node.n5{top:78%;left:82%;animation-delay:.4s}.node.n6{top:50%;left:12%;animation-delay:1.2s}
@keyframes nodepulse{0%,100%{opacity:.2;transform:scale(.7)}50%{opacity:.85;transform:scale(1.35)}}
@media(prefers-reduced-motion:reduce){.aigrid::before,.beam,.node{animation:none}}

/* ============ SEO / AEO / GEO ============ */
