.geo::after{content:attr(data-ac);position:absolute;top:-24px;right:2px;font-family:var(--fdisp);
 font-weight:800;font-size:120px;line-height:1;color:rgba(255,200,10,.05);letter-spacing:-.04em}
.geo .ic{width:52px;height:52px;border-radius:14px;background:rgba(255,200,10,.12);
 display:grid;place-items:center;color:var(--yellow);margin-bottom:18px;position:relative;z-index:1}
.geo .ic svg{width:26px;height:26px}
.geo .ac{display:inline-block;font-family:var(--fdisp);font-weight:800;font-size:14px;letter-spacing:.14em;
