.hform .fine{font-size:11.5px;color:var(--mut2);margin-top:13px;text-align:center}
/* step + progress state — keyed off CLASSES so the wizard can appear multiple times per page */
.wcb.st1:checked ~ .wsteps .wstep.s1,.wcb.st2:checked ~ .wsteps .wstep.s2,.wcb.st3:checked ~ .wsteps .wstep.s3{display:block;animation:rvIn .4s both}
.wcb.st1:checked ~ .wprog-txt .wt.s1,.wcb.st2:checked ~ .wprog-txt .wt.s2,.wcb.st3:checked ~ .wprog-txt .wt.s3{display:inline}
.wcb.st1:checked ~ .wprog .pd:nth-child(1),
.wcb.st2:checked ~ .wprog .pd:nth-child(-n+2),
.wcb.st3:checked ~ .wprog .pd:nth-child(-n+3){background:var(--yellow)}

