.blog-thumb{aspect-ratio:16/9;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;
 color:var(--mut2);text-align:center;padding:16px;
 background:linear-gradient(rgba(255,200,10,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,200,10,.05) 1px,transparent 1px),#0a1729;
 background-size:24px 24px,24px 24px,100% 100%}
.blog-thumb .ico{width:42px;height:42px;border-radius:11px;background:rgba(255,200,10,.12);display:grid;place-items:center;color:var(--yellow)}
.blog-thumb .ico svg{width:21px;height:21px}
.blog-thumb small{font-size:11px}
.blog-body{padding:22px;display:flex;flex-direction:column;flex:1}
.blog-cat{font-size:11.5px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--yellow);margin-bottom:10px}
.blog-body h3{font-size:18px;margin-bottom:10px;line-height:1.3}
.blog-body p{font-size:14px;color:var(--mut);flex:1;margin-bottom:14px}
.blog-more{font-size:14px;font-weight:700;color:var(--yellow);display:inline-flex;align-items:center;gap:6px}
.blog-more svg{width:15px;height:15px}

/* contact */
.contact-grid{display:grid;grid-template-columns:1fr .85fr;gap:40px;align-items:start}
.contact-grid>*{min-width:0}
.ci{display:grid;gap:14px}
.ci-item{display:flex;gap:14px;background:var(--navy2);border:1px solid var(--line);border-radius:14px;padding:18px 20px;min-width:0}
.ci-item .ic{width:44px;height:44px;border-radius:12px;background:rgba(255,200,10,.12);display:grid;place-items:center;color:var(--yellow);flex-shrink:0}
.ci-item .ic svg{width:22px;height:22px}
.ci-item h4{font-size:15.5px;margin-bottom:3px}
.ci-item p,.ci-item a{font-size:14.5px;color:var(--mut);overflow-wrap:anywhere}
.ci-item a:hover{color:var(--yellow)}

/* ============ THANK YOU ============ */
.ty{position:relative;overflow:hidden;padding:96px 0 84px;text-align:center;background:
 radial-gradient(760px 460px at 50% -10%,rgba(255,200,10,.16),transparent 62%)}
.ty-in{max-width:720px;margin:0 auto}
.ty-mas{width:104px;margin:0 auto 20px;filter:drop-shadow(0 14px 30px rgba(0,0,0,.5))}
.ty-badge{display:inline-flex;align-items:center;gap:8px;padding:8px 16px;border-radius:100px;
 background:rgba(47,208,122,.14);border:1px solid rgba(47,208,122,.4);color:var(--green);
 font-weight:700;font-size:14px;margin-bottom:20px}
.ty-badge svg{width:16px;height:16px}
.ty h1{font-size:clamp(30px,4.6vw,52px);margin-bottom:18px}
.ty-lead{font-size:19px;color:var(--mut);max-width:600px;margin:0 auto 30px}

/* ============ RESPONSIVE ============ */
@media(max-width:980px){
 .hero-grid{grid-template-columns:1fr;gap:48px}
 .hero-vis{max-width:520px;margin:0 auto;width:100%}
 .mb-grid{grid-template-columns:1fr;gap:16px}
 .mb-copy{text-align:center}.mb-copy p{margin-left:auto;margin-right:auto}
 .mb-copy .row{justify-content:center}
 .mb-vis{min-height:360px}
 .mb-glow{max-width:84%}.mb-ring.r1{max-width:80%}.mb-ring.r2{max-width:62%}
 .mb-tag.t1{left:0}.mb-tag.t2{right:0}
 .ai-grid,.tech-grid{grid-template-columns:1fr;gap:34px}
 .agy .box{grid-template-columns:1fr;padding:40px 30px}
 .pgrid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .sc-grid{grid-template-columns:1fr;gap:26px}
 .sc-hero .bframe{transform:none}
 .clients-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .rev-grid{grid-template-columns:1fr}
 .story-grid{grid-template-columns:1fr;gap:30px}
 .contact-grid{grid-template-columns:1fr;gap:30px}
 .val-grid,.blog-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .geo-grid{grid-template-columns:1fr;gap:16px}
 .steps{grid-template-columns:1fr;gap:16px}
 .step .arw{display:none}
 .fgrid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .tiers{grid-template-columns:1fr;max-width:460px;margin:0 auto}
}
@media(max-width:640px){
 .sec{padding:64px 0}
 .hero{padding:54px 0 72px}
 .final{padding:72px 0}
 .pgrid,.fgrid,.clients-grid,.val-grid,.blog-grid{grid-template-columns:1fr}
 .wait{flex-direction:column}
 .wait .btn{width:100%;justify-content:center}
 .proof-in{gap:18px}.proof .tech{gap:16px}
 .mbar{display:flex}
 body{padding-bottom:70px}
 .hv-badge{width:74px;top:-20px;right:-6px}
 .ft-grid{grid-template-columns:1fr 1fr;gap:30px}
 .ft-brand{grid-column:1/-1}
}
@media(max-width:420px){
 .ft-grid{grid-template-columns:1fr}
 .hero h1 .u{white-space:normal}
}
